// Mechanical summaries for catalog entries, paraphrased from the SR5 core
// rulebook's own rules text (Attributes p. 51-52, Qualities p. 71-87,
// Complex Forms p. 251-253, Rituals p. 296-298, Adept Powers p. 308-311,
// Mentor Spirits p. 320-324, Spells p. 283-294). The backend catalog itself
// carries no description field (see CatalogContract) — these are original,
// condensed paraphrases, not reproductions of the book's prose.

const ATTRIBUTE_DESCRIPTIONS: Record<string, string> = {
  body: 'Physical health and resiliency — how much damage you can take, how well you resist harm, and how fast you recover from poison and disease.',
  agility: 'Coordination, flexibility, and balance — the key attribute for landing hits in combat, and for sneaking, climbing, or any task needing a steady, dexterous touch.',
  reaction: 'Reflexes and awareness — how quickly you respond to danger, helping decide turn order in combat and your chances of dodging an attack.',
  strength: 'Raw physical power — how hard you hit, how much you can lift or carry, and how well you climb, run, and swim.',
  willpower: 'Mental toughness — your ability to push through adversity, resist spellcasting Drain, and stay upright after being hurt or intimidated.',
  logic: 'Rational, analytical thinking — used for repairing machinery, hacking, treating injuries, and resisting Drain as a hermetic mage.',
  intuition: 'Gut instinct — helps you notice danger, anticipate ambushes, and pick up a trail before your conscious mind catches up.',
  charisma: 'Force of personality — your persuasiveness and charm in social situations, and the attribute shamanic mages use to resist Drain.',
  edge: 'Raw luck — spent, not rolled, to buy specific game-changing effects like extra dice, a reroll, or shrugging off a critical glitch.',
  essence: 'A measure of your remaining humanity. Starts at 6 and is spent whenever you install cyberware or bioware; losses also drag down Magic and Resonance, and hitting 0 is fatal.',
  magic: 'How strong a spellcaster or adept you are. Sits at 0 for anyone without magical training, and fuels both spellcasting power and adept abilities.',
  resonance: 'A technomancer’s equivalent of Magic — the strength of their innate, toolless connection to the Matrix.',
}

const PATH_DESCRIPTIONS: Record<string, string> = {
  Mundane: 'No connection to Magic or Resonance. The character relies entirely on skills, gear, and augmentation.',
  Magician: 'Full sorcery and conjuring. Casts from the whole spell list, summons and binds spirits of a chosen tradition, and can perceive astrally at will.',
  MysticAdept: 'Splits Magic between spellcasting and Power Points, bought separately with Karma. Flexible, but thinner in both directions than a pure Magician or Adept.',
  Adept: 'No spellcasting. Every point of Magic buys Power Points spent on adept powers that sharpen the body and senses directly.',
  AspectedMagician: 'Access to only one magical skill group — Sorcery, Conjuring, or Enchanting. Cheaper in priority than a full Magician, at the cost of the other two.',
  Technomancer: 'A living connection to the Matrix in place of Magic. Resonance fuels sprites and complex forms instead of spirits and spells.',
}

const TRADITION_DESCRIPTIONS: Record<string, string> = {
  hermetic: 'Magic treated as a formal, learned science. Drain resists on Logic + Willpower, and spirits summoned are drawn from the elemental list.',
  shamanic: 'Magic practiced through relationship with totem spirits. Drain resists on Charisma + Willpower, and spirits summoned are drawn from the elemental list.',
}

const ASPECTED_VALUE_DESCRIPTIONS: Record<string, string> = {
  sorcery: 'Spells and rituals, cast and resisted exactly as a full Magician would — but no conjuring or enchanting.',
  conjuring: 'Summoning, binding, and banishing spirits — but no spellcasting or enchanting.',
  enchanting: 'Crafting foci, alchemical preparations, and other enchanted items — but no spellcasting or conjuring.',
}

